CREATE TABLE `notifications` (`id` CHAR(36) NOT NULL,`user_id` CHAR(36) NOT NULL,`type` VARCHAR(100) NOT NULL,`title` VARCHAR(255) NOT NULL,`body` TEXT NOT NULL,`entity_type` VARCHAR(100) NULL,`entity_id` CHAR(36) NULL,`metadata` JSON NULL,`dedupe_key` VARCHAR(255) NULL,`read_at` DATETIME(3) NULL,`expires_at` DATETIME(3) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE INDEX `notifications_dedupe_key_key`(`dedupe_key`),INDEX `notifications_user_id_created_at_idx`(`user_id`,`created_at`),INDEX `notifications_user_id_read_at_idx`(`user_id`,`read_at`),INDEX `notifications_created_at_idx`(`created_at`),INDEX `notifications_type_idx`(`type`),INDEX `notifications_entity_type_entity_id_idx`(`entity_type`,`entity_id`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
